def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the full-width separator.
    sep = next((r for r, row in enumerate(grid)
                if all(v == 2 for v in row)), None)
    if sep is None:
        return out

    occupied_rows = [r for r in range(h)
                     if any(v not in (2, 4) for v in grid[r])]
    if not occupied_rows:
        return out

    top, bottom = min(occupied_rows), max(occupied_rows)

    # Add an 8-line just beyond the object, toward the separator when
    # there is a blank row between them; otherwise put it on the far side.
    if bottom < sep:
        target = bottom + 1 if bottom + 1 < sep else top - 1
    else:
        target = top - 1 if top - 1 > sep else bottom + 1

    if 0 <= target < h and target != sep:
        out[target] = [8] * w
    return out
